// Look at the last N executions across the instance and flag the shapes that mean
// "something is quietly wrong", none of which an Error Workflow can see.
const cfg = $('Config').first().json;
const FAST_MS = Number(cfg.fastGreenMs) || 200;      // a "successful" run faster than this did no real work
const STREAK = Number(cfg.errorStreak) || 3;
const MIN_RUNS = Number(cfg.minRunsForFastGreen) || 10;
const base = String(cfg.baseUrl || '').replace(/\/$/, '');

const byWf = {};
for (const { json: e } of $input.all()) {
  const id = e.workflowId || 'unknown';
  const w = byWf[id] = byWf[id] || { id, name: e.workflowName || e.workflowData?.name || id, runs: [] };
  const started = e.startedAt ? new Date(e.startedAt).getTime() : null;
  const stopped = e.stoppedAt ? new Date(e.stoppedAt).getTime() : null;
  w.runs.push({
    id: e.id, status: e.status || (e.finished ? 'success' : 'error'),
    started, ms: started && stopped ? stopped - started : null, mode: e.mode,
  });
}

const findings = [];
for (const w of Object.values(byWf)) {
  w.runs.sort((a, b) => (b.started || 0) - (a.started || 0));   // newest first
  const success = w.runs.filter(r => r.status === 'success');
  const errors = w.runs.filter(r => r.status === 'error' || r.status === 'crashed');
  const link = base ? `${base}/workflow/${w.id}/executions` : `workflow ${w.id}`;

  // 1. consecutive failures, newest first
  let streak = 0;
  for (const r of w.runs) { if (r.status === 'error' || r.status === 'crashed') streak++; else break; }
  if (streak >= STREAK) findings.push({ kind: 'error-streak', workflow: w.name, workflowId: w.id, link,
    detail: `${streak} consecutive failed executions (latest ${new Date(w.runs[0].started).toISOString()})` });

  // 2. everything in the window failed
  if (errors.length >= STREAK && success.length === 0 && streak < STREAK) findings.push({ kind: 'all-failed', workflow: w.name, workflowId: w.id, link,
    detail: `${errors.length} executions in the window, none succeeded` });

  // 3. fast-green: successes finish in milliseconds while the runs that did real work failed
  const fast = success.filter(r => r.ms !== null && r.ms < FAST_MS).length;
  const slowErrors = errors.filter(r => r.ms !== null && r.ms > 1000).length;
  if (success.length >= MIN_RUNS && fast / success.length >= 0.9 && slowErrors > 0) {
    const med = success.map(r => r.ms).filter(x => x !== null).sort((a, b) => a - b);
    findings.push({ kind: 'fast-green', workflow: w.name, workflowId: w.id, link,
      detail: `${success.length} "successful" runs, ${Math.round(100 * fast / success.length)}% under ${FAST_MS} ms (median ${med[Math.floor(med.length / 2)]} ms); the ${slowErrors} run(s) that took real time all failed. The green runs are probably skipping the work.` });
  }
}

const summary = { workflowsSeen: Object.keys(byWf).length, executionsSeen: $input.all().length, findings: findings.length, checkedAt: new Date().toISOString() };
return findings.length ? findings.map(f => ({ json: { ...f, ...summary } })) : [{ json: { kind: 'all-quiet', ...summary } }];

const items = $input.all().map(i => i.json);
const s = items[0];
const icon = { 'error-streak': ':red_circle:', 'all-failed': ':black_circle:', 'fast-green': ':large_yellow_circle:' };
const lines = items.map(f => `${icon[f.kind] || ':white_circle:'} *${f.workflow}* — ${f.kind}
> ${f.detail}
> <${f.link}|executions>`);
return [{ json: { text: `*n8n execution audit* — ${s.findings} finding(s) across ${s.workflowsSeen} workflows / ${s.executionsSeen} executions

${lines.join('

')}

_Only an execution that did the work is a success. Fix the workflow, not the alert._` } }];
